\mathit{x}\mathbf{=}\mathit{v}_{\mathit{o}}\mathit{t} \\
\mathit{y}\mathbf{=}\frac{1}{2}\mathit{g}\mathit{t}^{2}
\end{array} \right.\ \mathbf{\Rightarrow}\mathit{y\ \ }\mathbf{=}\mathit{\ \ }\frac{\mathit{g}}{2\mathit{v}_{0}^{2}}\mathit{x}^{2}.$

Ta có $\left\{ \begin{array}{r}
\mathit{v}_{\mathit{x}}\mathit{\ \ }\mathbf{=}\mathit{\ \ }\mathit{v}_{0} \\
\mathit{v}_{\mathit{y}}\mathit{\ \ }\mathbf{=}\mathit{\ \ gt}
\end{array} \right.\ \mathbf{\Rightarrow}\mathit{v\ \ }\mathbf{=}\mathit{\ \ }\sqrt{\mathit{v}_{\mathit{x}}^{2}\mathit{\ }\mathit{\ }\mathbf{+}\mathit{\ \ v}_{\mathit{y}}^{2}}\mathit{\ \ }\mathbf{=}\mathit{\ \ }\sqrt{\mathit{v}_{0}^{2}\mathit{\ }\mathit{\ }\mathbf{+}\mathit{\ \ }\left( \mathit{gt} \right)^{2}}.$

